) AS source (Domain, BrandName, ClubId, ClubName, ClientId, IcePartnerId, Site, FusionPlatform, Members, TelemetryLocation, BusinessDataLocation, Environment)
ON target.ClubId = source.ClubId
WHEN MATCHED THEN UPDATE SET
    Domain = source.Domain, BrandName = source.BrandName, ClubName = source.ClubName, ClientId = source.ClientId,
    IcePartnerId = source.IcePartnerId, Site = source.Site, FusionPlatform = source.FusionPlatform, Members = source.Members,
    TelemetryLocation = source.TelemetryLocation, BusinessDataLocation = source.BusinessDataLocation, Environment = source.Environment
WHEN NOT MATCHED BY TARGET THEN
    INSERT (Domain, BrandName, ClubId, ClubName, ClientId, IcePartnerId, Site, FusionPlatform, Members, TelemetryLocation, BusinessDataLocation, Environment)
    VALUES (source.Domain, source.BrandName, source.ClubId, source.ClubName, source.ClientId, source.IcePartnerId, source.Site, source.FusionPlatform, source.Members, source.TelemetryLocation, source.BusinessDataLocation, source.Environment);
GO

